  diff --git a/web/src/keating/live-history.ts b/web/src/keating/live-history.ts
  new file mode 100644
  index 0000000..faafcc4
  --- /dev/null
  +++ b/web/src/keating/live-history.ts
  @@ -0,0 +1,66 @@
  +import type { LiveHistoryTurn } from "./speech";
  +
  +/**
  + * Build the conversation seed for a live voice session.
  + *
  + * A voice session opens a separate model connection, so without a seed the
  + * model has no idea what was just discussed in text and reintroduces itself
  + * mid-lesson. Only plain user/assistant text is replayed: tool traffic and
  + * generative-UI payloads mean nothing to a speech model and would waste the
  + * audio context window, which is far smaller than the text one.
  + */
  +export const DEFAULT_LIVE_HISTORY_TURNS = 12;
  +export const DEFAULT_LIVE_HISTORY_CHARS = 6000;
  +
  +function turnText(message: unknown): string {
  +	const content = (message as { content?: unknown }).content;
  +	if (typeof content === "string") return content.trim();
  +	if (Array.isArray(content)) {
  +		return content
  +			.filter((part) => part?.type === "text" && typeof part.text === "string")
  +			.map((part) => (part.text as string).trim())
  +			.filter(Boolean)
  +			.join(" ")
  +			.trim();
  +	}
  +	return "";
  +}
  +
  +function turnRole(message: unknown): LiveHistoryTurn["role"] | null {
  +	const role = (message as { role?: unknown }).role;
  +	if (role === "assistant") return "assistant";
  +	// "user-with-attachments" carries the same learner intent as a plain turn;
  +	// the attachments themselves are dropped along with the other non-text parts.
  +	if (role === "user" || role === "user-with-attachments") return "user";
  +	return null;
  +}
  +
  +export function buildLiveHistory(
  +	messages: readonly unknown[],
  +	options: { maxTurns?: number; maxChars?: number } = {},
  +): LiveHistoryTurn[] {
  +	const maxTurns = Math.max(0, options.maxTurns ?? DEFAULT_LIVE_HISTORY_TURNS);
  +	const maxChars = Math.max(0, options.maxChars ?? DEFAULT_LIVE_HISTORY_CHARS);
  +	if (maxTurns === 0 || maxChars === 0) return [];
  +
  +	const turns: LiveHistoryTurn[] = [];
  +	// Walk backwards so that when the budget runs out it is the oldest turns
  +	// that are dropped, not the ones the learner just spoke about.
  +	for (let i = messages.length - 1; i >= 0 && turns.length < maxTurns; i -= 1) {
  +		const role = turnRole(messages[i]);
  +		if (!role) continue;
  +		const text = turnText(messages[i]);
  +		if (!text) continue;
  +		turns.push({ role, text });
  +	}
  +	turns.reverse();
  +
  +	let total = 0;
  +	const budgeted: LiveHistoryTurn[] = [];
  +	for (let i = turns.length - 1; i >= 0; i -= 1) {
  +		total += turns[i].text.length;
  +		if (total > maxChars) break;
  +		budgeted.push(turns[i]);
  +	}
  +	return budgeted.reverse();
  +}

  diff --git a/web/src/keating/pcm-capture-worklet.ts b/web/src/keating/pcm-capture-worklet.ts
  new file mode 100644
  index 0000000..5ffd434
  --- /dev/null
  +++ b/web/src/keating/pcm-capture-worklet.ts
  @@ -0,0 +1,148 @@
  +/**
  + * Microphone capture on the audio rendering thread.
  + *
  + * The deprecated ScriptProcessorNode runs its callback on the main thread, so
  + * any React render or tool execution during a live session shows up as dropped
  + * or glitched microphone audio. An AudioWorklet runs on the audio thread and is
  + * unaffected by main-thread work.
  + *
  + * The worklet is shipped as a source string and loaded from a blob URL rather
  + * than a separate bundled entry point — worklet modules cannot share the app's
  + * module graph anyway, and this keeps it working under any bundler config.
  + */
  +
  +/** Frames per posted chunk. ~85ms at 16kHz: small enough to stay responsive. */
  +const CHUNK_FRAMES = 1365;
  +
  +const WORKLET_SOURCE = `
  +class PcmCaptureProcessor extends AudioWorkletProcessor {
  +  constructor(options) {
  +    super();
  +    this.chunkFrames = (options && options.processorOptions && options.processorOptions.chunkFrames) || ${CHUNK_FRAMES};
  +    this.buffer = new Float32Array(this.chunkFrames);
  +    this.offset = 0;
  +  }
  +
  +  process(inputs) {
  +    const channel = inputs[0] && inputs[0][0];
  +    // No input yet (or the track ended): keep the processor alive regardless.
  +    if (!channel) return true;
  +
  +    for (let i = 0; i < channel.length; i += 1) {
  +      this.buffer[this.offset] = channel[i];
  +      this.offset += 1;
  +      if (this.offset === this.chunkFrames) {
  +        // Convert on the audio thread so the main thread only sees bytes.
  +        const pcm = new Int16Array(this.chunkFrames);
  +        for (let j = 0; j < this.chunkFrames; j += 1) {
  +          const sample = Math.max(-1, Math.min(1, this.buffer[j]));
  +          pcm[j] = sample < 0 ? sample * 0x8000 : sample * 0x7fff;
  +        }
  +        this.port.postMessage(pcm.buffer, [pcm.buffer]);
  +        this.offset = 0;
  +      }
  +    }
  +    return true;
  +  }
  +}
  +
  +registerProcessor("keating-pcm-capture", PcmCaptureProcessor);
  +`;
  +
  +export const PCM_CAPTURE_PROCESSOR = "keating-pcm-capture";
  +
  +let moduleUrl: string | null = null;
  +
  +function workletModuleUrl(): string {
  +	if (moduleUrl === null) {
  +		moduleUrl = URL.createObjectURL(new Blob([WORKLET_SOURCE], { type: "application/javascript" }));
  +	}
  +	return moduleUrl;
  +}
  +
  +export interface PcmCaptureHandle {
  +	readonly context: AudioContext;
  +	readonly stream: MediaStream;
  +	stop(): void;
  +}
  +
  +/** Base64-encode raw PCM bytes for transports that carry audio inside JSON. */
  +export function encodePcmChunk(buffer: ArrayBuffer): string {
  +	const bytes = new Uint8Array(buffer);
  +	let binary = "";
  +	// Chunked to avoid blowing the argument limit on long buffers.
  +	const stride = 0x8000;
  +	for (let i = 0; i < bytes.length; i += stride) {
  +		binary += String.fromCharCode(...bytes.subarray(i, i + stride));
  +	}
  +	return btoa(binary);
  +}
  +
  +/**
  + * Capture microphone audio as base64 PCM chunks at the requested sample rate.
  + * Falls back to a ScriptProcessorNode where AudioWorklet is unavailable.
  + */
  +export async function startPcmCapture(options: {
  +	sampleRate: number;
  +	onChunk: (base64: string) => void;
  +}): Promise<PcmCaptureHandle> {
  +	if (typeof navigator === "undefined" || !navigator.mediaDevices?.getUserMedia) {
  +		throw new Error("Microphone unavailable for live voice.");
  +	}
  +	const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
  +	const context = new AudioContext({ sampleRate: options.sampleRate });
  +	const source = context.createMediaStreamSource(stream);
  +
  +	let disposed = false;
  +	let teardown = () => {};
  +
  +	if (context.audioWorklet) {
  +		await context.audioWorklet.addModule(workletModuleUrl());
  +		const node = new AudioWorkletNode(context, PCM_CAPTURE_PROCESSOR, {
  +			numberOfInputs: 1,
  +			numberOfOutputs: 0,
  +			processorOptions: { chunkFrames: CHUNK_FRAMES },
  +		});
  +		node.port.onmessage = (event: MessageEvent<ArrayBuffer>) => {
  +			if (!disposed) options.onChunk(encodePcmChunk(event.data));
  +		};
  +		source.connect(node);
  +		teardown = () => {
  +			node.port.onmessage = null;
  +			try { node.disconnect(); } catch {}
  +		};
  +	} else {
  +		const processor = context.createScriptProcessor(4096, 1, 1);
  +		processor.onaudioprocess = (event) => {
  +			if (disposed) return;
  +			const input = event.inputBuffer.getChannelData(0);
  +			const pcm = new Int16Array(input.length);
  +			for (let i = 0; i < input.length; i += 1) {
  +				const sample = Math.max(-1, Math.min(1, input[i]));
  +				pcm[i] = sample < 0 ? sample * 0x8000 : sample * 0x7fff;
  +			}
  +			options.onChunk(encodePcmChunk(pcm.buffer));
  +		};
  +		source.connect(processor);
  +		// A ScriptProcessorNode only runs while connected to a destination; the
  +		// output buffer is left silent so the mic is not echoed back.
  +		processor.connect(context.destination);
  +		teardown = () => {
  +			processor.onaudioprocess = null;
  +			try { processor.disconnect(); } catch {}
  +		};
  +	}
  +
  +	return {
  +		context,
  +		stream,
  +		stop() {
  +			if (disposed) return;
  +			disposed = true;
  +			teardown();
  +			try { source.disconnect(); } catch {}
  +			try { void context.close(); } catch {}
  +			stream.getTracks().forEach((track) => track.stop());
  +		},
  +	};
  +}

  diff --git a/web/src/keating/speech-providers/live-session-shared.ts b/web/src/keating/speech-providers/live-session-shared.ts
