  @@ -0,0 +1,155 @@
  +/**
  + * Plumbing shared by every duplex speech provider.
  + *
  + * Keating drives providers at different capability tiers, but a live session
  + * must look the same to the rest of the app regardless of which provider is
  + * behind it — persistence, replay, and the /live surface all consume the
  + * canonical event stream. Keeping the bridge and the tool-call lifecycle here
  + * (rather than duplicated per provider) is what makes the tier-parity test
  + * meaningful.
  + */
  +import type { RealtimeTelemetry } from "../observability";
  +import {
  +	conversationEvent,
  +	type ConversationEvent,
  +	type JsonValue,
  +	type ProtocolError,
  +} from "../protocol";
  +import type { LiveSpeechToolCall } from "../speech";
  +
  +export type LiveProviderId = "openai" | "google";
  +
  +export function randomId(prefix: string): string {
  +	const id = typeof crypto !== "undefined" && typeof crypto.randomUUID === "function"
  +		? crypto.randomUUID()
  +		: `${Date.now()}-${Math.random().toString(36).slice(2)}`;
  +	return `${prefix}-${id}`;
  +}
  +
  +export function jsonValue(value: unknown): JsonValue {
  +	if (value === undefined) return null;
  +	try {
  +		return JSON.parse(JSON.stringify(value)) as JsonValue;
  +	} catch {
  +		return String(value);
  +	}
  +}
  +
  +export function jsonRecord(value: unknown): Record<string, JsonValue> {
  +	const converted = jsonValue(value);
  +	return converted && typeof converted === "object" && !Array.isArray(converted)
  +		? converted as Record<string, JsonValue>
  +		: {};
  +}
  +
  +export function protocolError(error: unknown, code: string, provider: LiveProviderId): ProtocolError {
  +	return {
  +		code,
  +		message: error instanceof Error ? error.message : String(error),
  +		provider,
  +	};
  +}
  +
  +export interface RealtimeCanonicalBridge {
  +	readonly sessionId: string;
  +	readonly runId: string;
  +	emit<T extends ConversationEvent["type"]>(
  +		type: T,
  +		payload: Extract<ConversationEvent, { type: T }>["payload"],
  +	): void;
  +}
  +
  +export function createRealtimeCanonicalBridge(
  +	onEvent?: (event: ConversationEvent) => void,
  +	ids: { sessionId?: string; runId?: string } = {},
  +): RealtimeCanonicalBridge {
  +	const sessionId = ids.sessionId ?? randomId("voice-session");
  +	const runId = ids.runId ?? randomId("voice-run");
  +	let sequence = 0;
  +	return {
  +		sessionId,
  +		runId,
  +		emit(type, payload) {
  +			if (!onEvent) return;
  +			onEvent(conversationEvent(type, payload as never, {
  +				id: randomId("voice-event"),
  +				sequence: sequence++,
  +				timestamp: new Date().toISOString(),
  +				sessionId,
  +				runId,
  +			}));
  +		},
  +	};
  +}
  +
  +export interface LiveToolCallOptions {
  +	call: LiveSpeechToolCall;
  +	provider: LiveProviderId;
  +	canonical: RealtimeCanonicalBridge;
  +	telemetry: RealtimeTelemetry;
  +	execute: (call: LiveSpeechToolCall) => Promise<unknown>;
  +	/** Send a successful result back over the provider's transport. */
  +	respond: (callId: string, output: unknown) => void;
  +	/**
  +	 * Send a failure back over the provider's transport. Providers differ in
  +	 * whether they have a dedicated error shape, so each supplies its own.
  +	 */
  +	respondError: (callId: string, message: string) => void;
  +}
  +
  +/**
  + * Run one tool call through the canonical lifecycle.
  + *
  + * The requested/started events are emitted before execution begins so a slow
  + * tool still shows up immediately in the UI, and the transport response is sent
  + * on both the success and failure paths — a live session that never answers a
  + * function call will stall until the provider times it out.
  + */
  +export async function runLiveToolCall(options: LiveToolCallOptions): Promise<void> {
  +	const { call, provider, canonical, telemetry, execute, respond, respondError } = options;
  +
  +	canonical.emit("tool.requested", {
  +		callId: call.callId,
  +		name: call.name,
  +		arguments: jsonRecord(call.arguments),
  +	});
  +	canonical.emit("tool.started", { callId: call.callId });
  +	telemetry.emit("tool.started", { provider, toolName: call.name });
  +	const startedAt = telemetry.start();
  +
  +	try {
  +		const output = await execute(call);
  +		canonical.emit("tool.completed", { callId: call.callId, result: jsonValue(output) });
  +		telemetry.emit(
  +			"tool.completed",
  +			{ provider, toolName: call.name, outcome: "success" },
  +			telemetry.durationSince(startedAt),
  +		);
  +		respond(call.callId, output);
  +	} catch (error) {
  +		canonical.emit("tool.failed", {
  +			callId: call.callId,
  +			error: protocolError(error, "tool_execution_failed", provider),
  +		});
  +		telemetry.emit(
  +			"tool.completed",
  +			{ provider, toolName: call.name, outcome: "failed" },
  +			telemetry.durationSince(startedAt),
  +		);
  +		respondError(call.callId, error instanceof Error ? error.message : String(error));
  +	}
  +}
  +
  +/** Parse a provider's JSON-encoded tool arguments without throwing. */
  +export function parseToolArguments(raw: unknown): Record<string, unknown> {
  +	if (raw && typeof raw === "object" && !Array.isArray(raw)) return raw as Record<string, unknown>;
  +	if (typeof raw !== "string" || raw.length === 0) return {};
  +	try {
  +		const parsed = JSON.parse(raw);
  +		return parsed && typeof parsed === "object" && !Array.isArray(parsed)
  +			? parsed as Record<string, unknown>
  +			: {};
  +	} catch {
  +		return {};
  +	}
  +}

  diff --git a/web/src/keating/video-capture.ts b/web/src/keating/video-capture.ts
  new file mode 100644
  index 0000000..0704370
  --- /dev/null
  +++ b/web/src/keating/video-capture.ts
  @@ -0,0 +1,287 @@
  +/**
  + * Provider-agnostic frame capture for live sessions.
  + *
  + * Both realtime providers Keating targets consume sampled JPEG frames rather
  + * than a continuous video track — Gemini Live has a dedicated video lane capped
  + * at 1 fps, and GPT Realtime accepts still images as conversation items. So
  + * there is one capture pipeline here and the providers supply their own sink.
  + *
  + * Nothing in this module may import provider types.
  + */
  +
  +/** Both providers cap video at one frame per second. */
  +export const MIN_FRAME_INTERVAL_MS = 1000;
  +export const DEFAULT_MAX_EDGE = 768;
  +export const DEFAULT_JPEG_QUALITY = 0.6;
  +/**
  + * Histogram distance below which a frame is considered a repeat of the previous
  + * one and skipped. Tuned to drop a static desk/screen while still catching a
  + * page scroll or a hand entering frame.
  + */
  +export const DEFAULT_SIMILARITY_THRESHOLD = 0.02;
  +
  +const HISTOGRAM_BINS = 32;
  +
  +export type VideoSource = "camera" | "screen";
  +
  +export interface VideoCaptureOptions {
  +	source?: VideoSource;
  +	/** Milliseconds between sampled frames. Floored to MIN_FRAME_INTERVAL_MS. */
  +	intervalMs?: number;
  +	/** Longest edge of the encoded frame, in pixels. */
  +	maxEdge?: number;
  +	jpegQuality?: number;
  +	/** Set to 0 to emit every frame regardless of similarity. */
  +	similarityThreshold?: number;
  +}
  +
  +export interface NormalizedCaptureOptions {
  +	source: VideoSource;
  +	intervalMs: number;
  +	maxEdge: number;
  +	jpegQuality: number;
  +	similarityThreshold: number;
  +}
  +
  +export interface CapturedFrame {
  +	/** Base64 JPEG payload, no data-URL prefix. */
  +	data: string;
  +	/** Full data URL, which is what the OpenAI image content part wants. */
  +	dataUrl: string;
  +	mimeType: "image/jpeg";
  +	width: number;
  +	height: number;
  +	capturedAt: number;
  +}
  +
  +export type FrameListener = (frame: CapturedFrame) => void;
  +
  +export interface VideoCaptureHandle {
  +	/** Live stream, for rendering a local preview. */
  +	readonly stream: MediaStream;
  +	readonly source: VideoSource;
  +	/** Frames emitted so far, including on-demand captures. */
  +	readonly frameCount: number;
  +	/** Subscribe to the sampled frame feed. Returns an unsubscribe function. */
  +	onFrame(listener: FrameListener): () => void;
  +	/** Grab a frame immediately, bypassing the interval and similarity skip. */
  +	captureFrameNow(): Promise<CapturedFrame | null>;
  +	stop(): void;
  +}
  +
  +export function normalizeCaptureOptions(options: VideoCaptureOptions = {}): NormalizedCaptureOptions {
  +	return {
  +		source: options.source === "screen" ? "screen" : "camera",
  +		intervalMs: Math.max(MIN_FRAME_INTERVAL_MS, Math.floor(options.intervalMs ?? MIN_FRAME_INTERVAL_MS)),
  +		maxEdge: Math.max(64, Math.floor(options.maxEdge ?? DEFAULT_MAX_EDGE)),
  +		jpegQuality: Math.min(1, Math.max(0.1, options.jpegQuality ?? DEFAULT_JPEG_QUALITY)),
  +		similarityThreshold: Math.max(0, options.similarityThreshold ?? DEFAULT_SIMILARITY_THRESHOLD),
  +	};
  +}
  +
  +/**
  + * Scale a frame so its longest edge is at most maxEdge, preserving aspect
  + * ratio. Frames already within budget are left alone — upscaling would only
  + * cost tokens without adding detail.
  + */
  +export function computeCaptureSize(
  +	width: number,
  +	height: number,
  +	maxEdge: number,
  +): { width: number; height: number } {
  +	if (width <= 0 || height <= 0) return { width: 0, height: 0 };
  +	const longest = Math.max(width, height);
  +	if (longest <= maxEdge) return { width: Math.round(width), height: Math.round(height) };
  +	const scale = maxEdge / longest;
  +	return {
  +		width: Math.max(1, Math.round(width * scale)),
  +		height: Math.max(1, Math.round(height * scale)),
  +	};
  +}
  +
  +/**
  + * Normalized luma histogram over RGBA pixel data. Cheap enough to run on every
  + * candidate frame and stable against sensor noise, which a per-pixel diff is
  + * not.
  + */
  +export function lumaHistogram(pixels: ArrayLike<number>, bins = HISTOGRAM_BINS): Float64Array {
  +	const histogram = new Float64Array(bins);
  +	const pixelCount = Math.floor(pixels.length / 4);
  +	if (pixelCount === 0) return histogram;
  +	for (let i = 0; i < pixelCount; i += 1) {
  +		const offset = i * 4;
  +		// Rec. 601 luma; the exact weights matter less than being consistent.
  +		const luma = 0.299 * pixels[offset] + 0.587 * pixels[offset + 1] + 0.114 * pixels[offset + 2];
  +		const bin = Math.min(bins - 1, Math.floor((luma / 256) * bins));
  +		histogram[bin] += 1;
  +	}
  +	for (let i = 0; i < bins; i += 1) histogram[i] /= pixelCount;
  +	return histogram;
  +}
  +
  +/** Total variation distance between two normalized histograms, in [0, 1]. */
  +export function histogramDistance(a: ArrayLike<number>, b: ArrayLike<number>): number {
  +	if (a.length !== b.length) return 1;
  +	let sum = 0;
  +	for (let i = 0; i < a.length; i += 1) sum += Math.abs(a[i] - b[i]);
  +	return sum / 2;
  +}
  +
  +export function framesAreSimilar(
  +	previous: ArrayLike<number> | null,
  +	next: ArrayLike<number>,
  +	threshold: number,
  +): boolean {
  +	if (previous === null || threshold <= 0) return false;
  +	return histogramDistance(previous, next) < threshold;
  +}
  +
  +/**
  + * True when a frame should not be sent: the document is hidden, or the frame is
  + * indistinguishable from the last one we sent. Extracted so the policy is
  + * testable without a camera.
  + */
  +export function shouldSkipFrame(input: {
  +	documentHidden: boolean;
  +	previousHistogram: ArrayLike<number> | null;
  +	nextHistogram: ArrayLike<number>;
  +	similarityThreshold: number;
  +}): boolean {
  +	if (input.documentHidden) return true;
  +	return framesAreSimilar(input.previousHistogram, input.nextHistogram, input.similarityThreshold);
  +}
  +
  +async function requestStream(source: VideoSource): Promise<MediaStream> {
  +	if (typeof navigator === "undefined" || !navigator.mediaDevices) {
  +		throw new Error("Video capture is unavailable in this environment.");
  +	}
  +	if (source === "screen") {
  +		if (!navigator.mediaDevices.getDisplayMedia) {
  +			throw new Error("Screen sharing is not supported by this browser.");
  +		}
  +		return await navigator.mediaDevices.getDisplayMedia({ video: true, audio: false });
  +	}
  +	if (!navigator.mediaDevices.getUserMedia) {
  +		throw new Error("Camera capture is not supported by this browser.");
  +	}
  +	return await navigator.mediaDevices.getUserMedia({
  +		video: { width: { ideal: 1280 }, height: { ideal: 720 } },
  +		audio: false,
  +	});
  +}
  +
  +/**
  + * Begin sampling frames from the camera or screen. The returned handle is inert
  + * until something subscribes via onFrame; the timer runs regardless so that
  + * captureFrameNow always has a warm video element.
  + */
  +export async function startVideoCapture(options: VideoCaptureOptions = {}): Promise<VideoCaptureHandle> {
  +	const config = normalizeCaptureOptions(options);
  +	const stream = await requestStream(config.source);
  +
  +	const video = document.createElement("video");
  +	video.autoplay = true;
  +	video.muted = true;
  +	video.playsInline = true;
  +	video.srcObject = stream;
  +
  +	const canvas = document.createElement("canvas");
  +	const context = canvas.getContext("2d", { willReadFrequently: true });
  +
  +	const listeners = new Set<FrameListener>();
  +	let previousHistogram: Float64Array | null = null;
  +	let frameCount = 0;
  +	let stopped = false;
  +	let timer: ReturnType<typeof setInterval> | null = null;
  +
  +	await video.play().catch(() => {
  +		// Autoplay of a muted local stream is permitted; a rejection here means
  +		// the track ended before playback started, which stop() will clean up.
  +	});
  +
  +	const grab = (options: { force: boolean }): CapturedFrame | null => {
  +		if (stopped || !context) return null;
  +		const width = video.videoWidth;
  +		const height = video.videoHeight;
  +		if (width === 0 || height === 0) return null;
  +
  +		const size = computeCaptureSize(width, height, config.maxEdge);
  +		canvas.width = size.width;
  +		canvas.height = size.height;
  +		context.drawImage(video, 0, 0, size.width, size.height);
  +
  +		const histogram = lumaHistogram(context.getImageData(0, 0, size.width, size.height).data);
  +		if (!options.force) {
  +			const skip = shouldSkipFrame({
  +				documentHidden: typeof document !== "undefined" && document.hidden,
  +				previousHistogram,
  +				nextHistogram: histogram,
  +				similarityThreshold: config.similarityThreshold,
  +			});
  +			if (skip) return null;
  +		}
  +		previousHistogram = histogram;
  +
  +		const dataUrl = canvas.toDataURL("image/jpeg", config.jpegQuality);
  +		frameCount += 1;
  +		return {
  +			data: dataUrl.slice(dataUrl.indexOf(",") + 1),
  +			dataUrl,
  +			mimeType: "image/jpeg",
  +			width: size.width,
  +			height: size.height,
  +			capturedAt: Date.now(),
  +		};
  +	};
  +
  +	const emit = (frame: CapturedFrame | null) => {
  +		if (!frame) return;
  +		for (const listener of listeners) {
  +			try {
  +				listener(frame);
  +			} catch (error) {
  +				console.warn("[keating:video] frame listener failed", error);
  +			}
  +		}
  +	};
  +
  +	timer = setInterval(() => {
  +		if (listeners.size === 0) return;
  +		emit(grab({ force: false }));
  +	}, config.intervalMs);
  +
  +	const stop = () => {
  +		if (stopped) return;
  +		stopped = true;
  +		if (timer !== null) clearInterval(timer);
  +		timer = null;
  +		listeners.clear();
  +		stream.getTracks().forEach((track) => track.stop());
  +		video.srcObject = null;
  +		try {
  +			video.remove();
  +		} catch {}
  +	};
  +
  +	// A screen share ends when the user clicks the browser's "stop sharing"
  +	// chrome, which surfaces only as a track ending.
  +	stream.getVideoTracks().forEach((track) => track.addEventListener("ended", stop, { once: true }));
  +
  +	return {
  +		stream,
  +		source: config.source,
  +		get frameCount() {
  +			return frameCount;
  +		},
  +		onFrame(listener) {
  +			listeners.add(listener);
  +			return () => listeners.delete(listener);
  +		},
  +		async captureFrameNow() {
  +			const frame = grab({ force: true });
  +			emit(frame);
  +			return frame;
  +		},
  +		stop,
  +	};
  +}

  diff --git a/web/src/pages/Live.tsx b/web/src/pages/Live.tsx
  new file mode 100644
  index 0000000..75c38ec
  --- /dev/null
  +++ b/web/src/pages/Live.tsx
  @@ -0,0 +1,526 @@
  +import { useCallback, useEffect, useMemo, useRef, useState } from "react";
  +import { Camera, MonitorUp, Power } from "lucide-react";
  +
  +import { Nav } from "../components/Nav";
  +import { css, cx } from "../../styled-system/css";
  +import {
  +	getLiveSpeechBridge,
  +	getSpeechProvider,
  +	loadWebSpeechSettings,
  +	primeSpeechAudio,
  +	resolveSpeechRealtimeTier,
  +	speechErrorMessage,
  +	type LiveSpeechSession,
  +	type LiveSpeechState,
  +} from "../keating/speech";
  +import { startVideoCapture, type VideoCaptureHandle } from "../keating/video-capture";
  +import type { ConversationEvent } from "../keating/protocol";
  +import { getProviderApiKey } from "../lib/provider-models";
  +
  +/**
  + * The live session surface.
  + *
  + * Keating's mascot is a CRT monitor with a face, so a live A/V session gets
  + * rendered as exactly that: the learner's camera feed becomes the phosphor
  + * screen behind the bezel, and Keating's own face takes over whenever he has
  + * nothing to look at. Status, tools, and transcript are all terminal readouts,
  + * matching the boot sequence and the landing hero.
  + */
  +
  +const STATE_LABEL: Record<LiveSpeechState, string> = {
  +	connecting: "connecting",
  +	listening: "listening",
  +	speaking: "speaking",
  +	closed: "standby",
  +};
  +
  +interface ToolEntry {
  +	callId: string;
  +	name: string;
  +	status: "running" | "completed" | "failed";
  +}
  +
  +interface TranscriptEntry {
  +	role: "user" | "assistant";
  +	text: string;
  +}
  +
  +/**
  + * Dotted leader between a label and its status, as in the boot sequence.
  + *
  + * The dots are a border rather than repeated glyphs: a run of non-breaking
  + * characters contributes its full width to max-content sizing and will drag the
  + * whole grid column wider than its cell.
  + */
  +function Leader({ label, value, tone }: { label: string; value: string; tone?: "ok" | "fail" | "pending" }) {
  +	return (
  +		<div className={css({ display: "flex", alignItems: "baseline", gap: "0.5rem", fontSize: "0.8125rem", minWidth: 0 })}>
  +			<span className={css({ minWidth: 0, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" })}>
  +				{label}
  +			</span>
  +			<span
  +				aria-hidden="true"
  +				className={css({
  +					flex: "1 1 auto",
  +					minWidth: "0.75rem",
  +					alignSelf: "center",
  +					borderBottom: "1px dotted currentColor",
  +					opacity: 0.35,
  +				})}
  +			/>
  +			<span
  +				className={css({
  +					whiteSpace: "nowrap",
  +					flexShrink: 0,
  +					color: tone === "fail"
  +						? "var(--red)"
  +						: tone === "pending"
  +							? "var(--amber)"
  +							: "var(--phosphor)",
  +				})}
  +			>
  +				{value}
  +			</span>
  +		</div>
  +	);
  +}
  +
  +export function Live() {
  +	const settings = useMemo(() => loadWebSpeechSettings(), []);
  +	const tier = useMemo(() => resolveSpeechRealtimeTier(settings), [settings]);
  +
  +	const [state, setState] = useState<LiveSpeechState>("closed");
  +	const [active, setActive] = useState(false);
  +	const [error, setError] = useState<string | null>(null);
  +	const [transcript, setTranscript] = useState<TranscriptEntry[]>([]);
  +	const [tools, setTools] = useState<ToolEntry[]>([]);
  +	const [framesSent, setFramesSent] = useState(0);
  +	const [firstAudioMs, setFirstAudioMs] = useState<number | null>(null);
  +	const [videoLive, setVideoLive] = useState(false);
  +
  +	const sessionRef = useRef<LiveSpeechSession | null>(null);
  +	const videoRef = useRef<VideoCaptureHandle | null>(null);
  +	const abortRef = useRef<AbortController | null>(null);
  +	const previewRef = useRef<HTMLVideoElement | null>(null);
  +	const transcriptRef = useRef<HTMLDivElement | null>(null);
  +	const startedAtRef = useRef<number>(0);
  +
  +	const appendTranscript = useCallback((role: "user" | "assistant", text: string) => {
  +		if (!text) return;
  +		setTranscript((prev) => {
  +			const last = prev[prev.length - 1];
  +			// Deltas from the same speaker coalesce; a change of speaker starts a
  +			// new line.
  +			if (last && last.role === role) {
  +				return [...prev.slice(0, -1), { role, text: last.text + text }];
  +			}
  +			return [...prev, { role, text }];
  +		});
  +	}, []);
  +
  +	// Keep the newest line in view without yanking the page around.
  +	useEffect(() => {
  +		const node = transcriptRef.current;
  +		if (node) node.scrollTop = node.scrollHeight;
  +	}, [transcript]);
  +
  +	const stop = useCallback(() => {
  +		abortRef.current?.abort();
  +		abortRef.current = null;
  +		void sessionRef.current?.stop().catch(() => {});
  +		sessionRef.current = null;
  +		videoRef.current?.stop();
  +		videoRef.current = null;
  +		if (previewRef.current) previewRef.current.srcObject = null;
  +		setVideoLive(false);
  +		setActive(false);
  +		setState("closed");
  +	}, []);
  +
  +	// A live session holds the microphone, the camera, and a paid socket; it
  +	// must not survive the user navigating away.
  +	useEffect(() => stop, [stop]);
  +
  +	const onConversationEvent = useCallback((event: ConversationEvent) => {
  +		switch (event.type) {
  +			case "tool.requested":
  +				setTools((prev) => [
  +					...prev,
  +					{ callId: event.payload.callId, name: event.payload.name, status: "running" },
  +				]);
  +				break;
  +			case "tool.completed":
  +			case "tool.failed":
  +				setTools((prev) => prev.map((entry) =>
  +					entry.callId === event.payload.callId
  +						? { ...entry, status: event.type === "tool.completed" ? "completed" : "failed" }
  +						: entry));
  +				break;
  +			default:
  +				break;
  +		}
  +	}, []);
  +
  +	const start = useCallback(async () => {
  +		setError(null);
  +		setTranscript([]);
  +		setTools([]);
  +		setFramesSent(0);
  +		setFirstAudioMs(null);
  +		setState("connecting");
  +		setActive(true);
  +		startedAtRef.current = Date.now();
  +
  +		const abort = new AbortController();
  +		abortRef.current = abort;
  +
  +		try {
  +			// Browsers only unlock audio playback inside a user gesture, and this
  +			// runs from the power button's handler.
  +			await primeSpeechAudio();
  +
  +			const provider = await getSpeechProvider(settings.providerId);
  +			if (!provider?.startLiveSession) {
  +				throw new Error("This speech provider cannot hold a live session. Pick OpenAI Realtime or Gemini Live in Settings → Speech.");
  +			}
  +
  +			let video: VideoCaptureHandle | null = null;
  +			if (settings.videoEnabled && tier.video) {
  +				try {
  +					video = await startVideoCapture({
  +						source: settings.videoSource,
  +						intervalMs: settings.frameIntervalMs,
  +					});
  +					videoRef.current = video;
